from math import isqrt

def prime_sum(limit):
    if limit <= 2: return 0
    sieve = bytearray(b"\x01") * limit
    sieve[0:2] = b"\x00\x00"
    for p in range(2, isqrt(limit-1)+1):
        if sieve[p]:
            start = p*p
            sieve[start:limit:p] = b"\x00" * (((limit-1-start)//p)+1)
    return sum(i for i, yes in enumerate(sieve) if yes)

def even_fibonacci_sum(limit):
    a, b, total = 1, 2, 0
    while a <= limit:
        if a % 2 == 0: total += a
        a, b = b, a+b
    return total

def linear_search(a, target):
    for i, value in enumerate(a):
        if value == target: return i
    return -1

def binary_search(a, target):
    lo, hi = 0, len(a)-1
    while lo <= hi:
        mid = lo + (hi-lo)//2
        if a[mid] == target: return mid
        if a[mid] < target: lo = mid+1
        else: hi = mid-1
    return -1

def selection_sort(values):
    a = list(values)
    for i in range(len(a)-1):
        j = min(range(i, len(a)), key=a.__getitem__)
        a[i], a[j] = a[j], a[i]
    return a

def insertion_sort(values):
    a = list(values)
    for i in range(1, len(a)):
        key, j = a[i], i-1
        while j >= 0 and a[j] > key:
            a[j+1] = a[j]
            j -= 1
        a[j+1] = key
    return a

if __name__ == "__main__":
    print(prime_sum(2_000_000))
    print(even_fibonacci_sum(4_000_000))
    print(selection_sort([3, 1, 2]))
    print(insertion_sort([3, 1, 2]))

