from statistics import mean, median, multimode

def ball_collide(a, b):
    x1, y1, r1 = a
    x2, y2, r2 = b
    if r1 < 0 or r2 < 0:
        raise ValueError("Radii must be nonnegative")
    return (x1-x2)**2 + (y1-y2)**2 <= (r1+r2)**2

def summary(values):
    if not values: raise ValueError("Nonempty data required")
    return mean(values), median(values), multimode(values)

